const TH15_RICE: int = 480;          // source etSprite(0, 8, 6): type 8 = rice, color 6
const TIME_LIMIT: int = 1824;
const OPENING_BUFFER: int = 120;

// Source bullet EX program (etEx/etExSet2 in GirlA04_at2):
//   idx0 ANIM(type 2, a=1) and idx1 BRIGHT(type 1048576, a=0) are birth presentation,
//   omitted per the approved birth-effect simplification.
//   idx2 VELTIME(type 2097152, a=60, r=1.0|4.0, s=-999999 keeps current angle).
//   idx3 LASER(type 134217728) + paired idx4 record (SHOOT_DATA) spawn a line laser and
//   delete the parent bullet (d low byte != 0).
// E/N/H: VELTIME target speed equals the initial 1.0, so the flight is unaccelerated.
// L: speed ramps 1.0 -> 4.0 over 60 frames (linear per-frame delta).
xformdef SHOT_PLAIN {
    wait(60);
    set_life(1);                     // source EX LASER deletes the parent bullet at laser birth
}

xformdef SHOT_ACCEL {
    step_speed(4fx, 60 + 65536 * EASE_LINEAR);
    wait(60);
    set_life(1);
}

// Line laser from the source EX LASER record:
//   a=0 line, b=8 sprite, c=6 color, d low byte != 0 -> delete parent,
//   r=-999999 keeps the bullet angle, s=6.0 (E/N/H) / 12.0 (L) travel speed,
//   m=32 line length (judged 0.8*L = 25.6), n=128 length-related travel limit,
//   paired record: r2=0 extra float, s2=16 source width -> target width 8 (w/4 half height).
// The source line travels (n-m)=96px then is cropped over m=32px, i.e. about n/s frames;
// a constant-width rod of the judged length with that active window approximates it.
async sub shot_to_laser() {
    wait(59);                        // bullet tasks first run one frame after creation
    var spd: fx = 6fx;
    var life: int = 21;              // 128 / 6
    if global(GVAR_RANK) >= RANK_LUNATIC {
        spd = 12fx;
        life = 11;                   // 128 / 12
    }
    var h: int = laser(6, $self_x, $self_y, $self_angle, 0fx, 8fx, 0, life, 0);
    if h >= 0 {
        lz_speed(h, spd, 25.6fx);
    }
}

// Source GirlA04_at2:371-440: one aimed rice shot per iteration, 80 iterations.
async sub girl_a04_attack() {
    var interval: int = 20;          // source !E20 !N20 !H15 !LO10
    if global(GVAR_RANK) == RANK_HARD {
        interval = 15;
    }
    if global(GVAR_RANK) >= RANK_LUNATIC {
        interval = 10;
    }
    wait(10 + rand(40));             // source wait(10 + RAND % 40)
    var i: int = 0;
    while i < 80 {                   // source $B = 80
        // source etAngle(0, ANGLE_PLAYER + RANDF2*0.08726646, 0.17453292); N=1 so only base angle
        var ra: int = rand(65536);
        var u: fx = (ra - 32768) as fx / 32768;
        var dir: angle = aim_player() + (((910fx * u) as int) as angle);
        // source ANIM a=1 birth retreat: position -= 4 * velocity (initial speed 1.0)
        var px: fx = $self_x - 4fx * cos(dir);
        var py: fx = $self_y - 4fx * sin(dir);
        if global(GVAR_RANK) >= RANK_LUNATIC {
            _ = fire(TH15_RICE, 6, px, py, 1fx, dir, SHOT_ACCEL, shot_to_laser);
        } else {
            _ = fire(TH15_RICE, 6, px, py, 1fx, dir, SHOT_PLAIN, shot_to_laser);
        }
        i = i + 1;
        wait(interval);
    }
}

// Source GirlA04:343-352 / GirlA04_at:354-369.
// anmSelect/anmSetMain/dropMain/dropExtra are presentation and drop, omitted.
async sub girl_a04(mirror: int, f0: angle) {
    set_hurtbox(12fx);               // source setHurtbox(24,24): circle radius 24*0.5
    set_hitbox(8fx);                 // source setHitbox(16,16): circle radius 16*0.5
    set_invuln(65535);               // training shell: real enemies run invulnerable
    spawn girl_a04_attack();         // source @GirlA04_at2() async
    var a0: angle = f0;
    var a1: angle = 0deg - 2048bam;  // -0.19634955 rad = -11.25deg
    var a2: angle = 45deg;           // 0.7853982 rad
    if mirror != 0 {
        // enmCreateM child mirror negates x: every written movement angle becomes pi - angle
        a0 = (32768 - (f0 as int)) as angle;
        a1 = 34816 as angle;         // pi + 11.25deg
        a2 = 135deg;                 // pi - 45deg
    }
    move_vel(0, a0, 3fx, EASE_LINEAR);                 // source moveVel(F0, 3.0)
    move_vel(120, a1, 2fx, EASE_QUAD_IN);              // source moveVelTime(120, 1, ..., 2.0)
    wait(120);
    move_vel(60, a2, 4fx, EASE_QUAD_OUT);              // source moveVelTime(60, 4, ..., 4.0)
    loop { wait(1000); }                               // source GirlA04_at_248 idle loop
}

// Source MainSub05:1550-1573: wait(80), A = 25/50 pairs, spawn left + mirrored right
// GirlA04 at x = -224 / +224, y = 64 +- 32, interval 40 (Easy) / 20, F0 = 22.5deg +- 20deg.
async sub wave() {
    wait(OPENING_BUFFER);
    wait(80);                        // source wait(80) at 1553
    var count: int = 50;             // source diffI($A, 25, 50, 50, 50)
    var interval: int = 20;          // source !E40 !N20 !H20 !LO20
    if global(GVAR_RANK) == RANK_EASY {
        count = 25;
        interval = 40;
    }
    var i: int = 0;
    while i < count {
        // source %F0 = 0.3926991 + RANDF2 * 0.34906584 (22.5deg +- 20deg)
        var rf: int = rand(65536);
        var uf: fx = (rf - 32768) as fx / 32768;
        var f0: angle = (4096 + ((3641fx * uf) as int)) as angle;
        // source y = 64 + RANDF2 * 32, sampled separately for each side
        var rl: int = rand(65536);
        var ul: fx = (rl - 32768) as fx / 32768;
        var yl: fx = 64fx + 32fx * ul;
        var rr: int = rand(65536);
        var ur: fx = (rr - 32768) as fx / 32768;
        var yr: fx = 64fx + 32fx * ur;
        _ = spawn_enemy(-224fx, yl, 50, 0, 1000, 0, girl_a04(0, f0));
        _ = spawn_enemy(224fx, yr, 50, 0, 1000, 0, girl_a04(1, f0));
        i = i + 1;
        wait(interval);
    }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, wave, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
